	@Test
	void pipelineAnchoredPlanReplansAfterFirstPostRestartCommit(@TempDir File dataDir) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(true)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		String query = "SELECT ?s WHERE { ?s <urn:p> ?o FILTER(?o = 7) }";
		SailRepository repository = repository(dataDir, config);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			connection.add(B, P, VF.createLiteral("6", XSD.INTEGER));
			var estimator = ((LmdbStore) repository.getSail()).getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			for (int i = 0; i < 4; i++) {
				estimator.rebuild();
			}
		}
		repository.shutDown();
		repository = repository(dataDir, config);
		try (RepositoryConnection connection = repository.getConnection()) {
			((LmdbStore) repository.getSail()).getBackingStore().getSketchBasedJoinEstimator().stop();
			assertEquals(Set.of(), rows(connection, query, "s"));
			assertEquals(Set.of(), rows(connection, query, "s"));

			connection.add(C, P, VF.createLiteral("7", XSD.INTEGER));

			// The first post-restart commit must move the data revision, so the anchored plan (a hard
			// committed-snapshot dependency) is replanned instead of served from the cache.
			TupleExpr replanned = explain(connection, query);
			assertNotEquals("true", replanned.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"),
					"the pre-commit anchored plan must not be served unchanged after the commit");
			assertEquals(Set.of("urn:c"), rows(connection, query, "s"),
					"a committed value-equal term must be visible after the first post-restart commit");
			// The replacement plan built at the new data revision replaces the stale family version and is served
			// from the cache again.
			TupleExpr replacement = explain(connection, query);
			assertEquals("true", replacement.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"),
					"the replacement plan must be publishable after the hard-dependency replan");
			// Executing the replacement observed new filter outcomes after its quality certificate was built.
			assertEquals("USE_AND_REFRESH", replacement.getStringMetricPlanned("optimizer.planCacheLookupOutcome"));
			assertEquals("SUSPECT", replacement.getStringMetricPlanned("optimizer.planCacheQualityState"));
			assertEquals("OUTSIDE", replacement.getStringMetricPlanned("optimizer.planCacheStabilityEnvelopeResult"));
			assertEquals("outside-stability-envelope",
					replacement.getStringMetricPlanned("optimizer.planCacheRefreshReason"));
		} finally {
			repository.shutDown();
		}
	}

	private static void assertRestartedPackedCacheFresh(File dataDir, boolean restart) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(true)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		String query = "SELECT ?s WHERE { ?s <urn:p> 7 }";
		SailRepository repository = repository(dataDir, config);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("5", XSD.INTEGER));
			connection.add(B, P, VF.createLiteral("6", XSD.INTEGER));
			var estimator = ((LmdbStore) repository.getSail()).getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			for (int i = 0; i < 4; i++) {
				estimator.rebuild();
			}
		}
		if (restart) {
			repository.shutDown();
			repository = repository(dataDir, config);
		}
		try (RepositoryConnection connection = repository.getConnection()) {
			((LmdbStore) repository.getSail()).getBackingStore().getSketchBasedJoinEstimator().stop();
			assertEquals(Set.of(), rows(connection, query, "s"));

			connection.add(C, P, VF.createLiteral("7", XSD.INTEGER));
			Set<String> afterCommit = rows(connection, query, "s");

			assertEquals(Set.of("urn:c"), afterCommit, "committed :c :p 7 must be visible (restart=" + restart + ")");
		} finally {
			repository.shutDown();
		}
	}

	private static SailRepository repository(File dataDir, LmdbStoreConfig config) {
		LmdbStore store = new LmdbStore(dataDir, config);
		if (Boolean.TRUE.equals(config.getSketchEstimatorEnabled())) {
			store.setExperimentalQueryOptimizations(true);
		}
		SailRepository repository = new SailRepository(store);
		repository.init();
		if (Boolean.TRUE.equals(config.getSketchEstimatorEnabled())) {
			assertSketchFixtureProfile(store);
		}
		return repository;
	}

	private static Set<String> rows(RepositoryConnection connection, String query, String... names) {
		Set<String> rows = new TreeSet<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			for (BindingSet bindingSet : result) {
				StringBuilder row = new StringBuilder();
				for (int index = 0; index < names.length; index++) {
					if (index > 0) {
						row.append('|');
					}
					row.append(bindingSet.getValue(names[index]) == null ? "UNBOUND"
							: bindingSet.getValue(names[index]).stringValue());
				}
				rows.add(row.toString());
			}
		}
		return rows;
	}

	private static TupleExpr explain(RepositoryConnection connection, String query) {
		return (TupleExpr) connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized).tupleExpr();
	}

	private static void assertSketchFixtureProfile(LmdbStore store) {
		try {
			assertTrue(store.getQueryExecutionPolicy().experimentalQueryOptimizations());
			assertNotNull(store.getBackingStore().getSketchBasedJoinEstimator());
		} catch (AssertionError failure) {
			try {
				store.shutDown();
			} catch (RuntimeException | Error closeFailure) {
				failure.addSuppressed(closeFailure);
			}
			throw failure;
		}
	}
